 1	//Exercicio 1.a)
 2	function sum (a:array<int>, i:int, j:int) :int
 3	decreases j
 4	reads a
 5	requires 0 <= i <= j <= a.Length
 6	{
 7	    if i == j then
 8	        0
 9	    else
10	        a[j-1] + sum(a, i, j-1)
11	}
