13	//Exercicio 1.b)
14	method query (a:array<int>, i:int, j:int) returns (s:int)
15	requires 0 <= i <= j <= a.Length
16	ensures s == sum(a, i, j) && s >= 0
17	{
18	    s := 0;
19	    var aux := i;
20	
21	    while (aux < j)
22	    invariant i <= aux <= j
23	    invariant s == sum(a, i, aux)
24	    decreases  j - aux
25	    {
26	        s := s + a[aux];
27	        aux := aux + 1;
28	    }
29	    return s;
30	}
31	
32	//Exercicio 1.c)
33	lemma queryLemma(a:array<int>, i:int, j:int, k:int)
34	    requires 0 <= i <= k <= j <= a.Length
35	    ensures  sum(a,i,k) + sum(a,k,j) == sum(a,i,j)
36	{
37	}
38	
39	method queryFast (a:array<int>, c:array<int>, i:int, j:int) returns (r:int)
40	requires is_prefix_sum_for(a,c) && 0 <= i <= j <= a.Length < c.Length
41	ensures r == sum(a, i,j)
42	{
43	    r := c[j] - c[i];
44	    queryLemma(a,0,j,i);
45	
46	    return r;
47	}
48	
49	predicate is_prefix_sum_for (a:array<int>, c:array<int>)
50	reads c, a
51	{
52	    a.Length + 1 == c.Length
53	    && c[0] == 0
54	    && forall j :: 1 <= j <= a.Length ==> c[j] == sum(a,0,j)
55	}
