58	datatype List<T> = Nil | Cons(head: T, tail: List<T>)
59	
60	method from_array<T>(a: array<T>) returns (l: List<T>)
61	requires a.Length > 0
62	ensures forall j::0 <= j < a.Length ==> mem(a[j],l)
63	{
64	    var i:= a.Length-1;
65	    l:= Nil;
66	
67	    while (i >= 0)
68	    invariant -1 <= i < a. Length
69	    invariant forall j:: i+1 <= j < a.Length ==> mem(a[j],l)
70	    {
71	        l := Cons(a[i], l);
72	        i := i - 1;
73	    }
74	
75	    return l;
76	}
77	
78	function mem<T(==)> (x: T, l:List<T>) : bool
79	decreases l
80	{
81	    match l
82	    case Nil => false
83	    case Cons(y,r)=> if (x==y) then true else mem(x,r)
84	}
